import json,copy,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1];A=R/'app/src/main/assets';report=[]
LIMIT='≈ — ориентировочная топография по доступным срезам, не доказанно выделенные волокна, стенки сумки или жидкость. Пунктир/контурные точки отличают учебный ориентир. Не использовать для вывода о целости, тендинопатии или бурсите. Независимая врачебная верификация не выполнена.'
class Overlay:
 def __init__(self,mod,base):
  self.mod=mod;self.d=json.loads((A/(mod+'-data.json')).read_text());self.l=json.loads((A/(mod+'-labels.json')).read_text());self.e=copy.deepcopy(json.loads((A/base).read_text()));self.e['revision']='1.49';self.e['pointPresentation']={};self.points=[];self.ribbons=[]
  self.s={s['sourceSeries']:s for s in self.d['series'] if '_dp' in s['id']};self.defs={}
  self.e['limitations']=[LIMIT]+[x for x in self.e['limitations'] if not x.startswith('Проверка 1.45:')]
 def define(self,id,name,note,group):
  self.defs[id]=(name,group);self.e['catalogNames'][str(id)]=name;self.e['structureNotes'][str(id)]=note+' '+LIMIT
 def add(self,id,se,rows):
  name,group=self.defs[id];s=self.s[se]
  for n,x,y in rows:
   f=s['frames'][n-1];a=self.e['seriesSlices'][s['id']][f['annotation']]
   p={'id':149000000+(0 if self.mod=='hip-mri' else 100000)+len(self.points),'structure':id,'name':'≈ '+name+' · ориентировочно','shortName':'≈ '+name,'filter':group,'category':'ligaments','x':x,'y':y,'approximate':True,'provenance':'manual-pd-topography-1.49'}
   a['points'].append(p);self.points.append({'series':s['id'],'frame':n,'imageSha256':f['sha256'],**p})
 def ribbon(self,id,se,rows):
  s=self.s[se]
  old=json.loads((A/'knee-mri-anatomy144.json').read_text())
  model=next(r for ss in old['seriesSlices'].values() for a in ss.values() for r in a['regions'] if r['structure']==id)
  for n,vs in rows:
   f=s['frames'][n-1];a=self.e['seriesSlices'][s['id']][f['annotation']];r=copy.deepcopy(model);r.update(vertices=vs,width=3,approximate=True,provenance='expected-anatomical-space-1.49');a['regions']=[q for q in a['regions'] if q['structure']!=id]+[r]
   self.ribbons.append({'series':s['id'],'frame':n,'imageSha256':f['sha256'],**r})
 def course(self,ids,group):
  for id in ids:self.e['pointPresentation'][str(id)]={'filter':group,'category':'ligaments'}
 def finish(self):
  for ss in self.e['seriesSlices'].values():
   for a in ss.values():a['points'].sort(key=lambda p:p['structure']);a['regions'].sort(key=lambda p:p['structure']);a['suppress']=sorted(set(a['suppress']))
  (A/(self.mod+'-anatomy149.json')).write_text(json.dumps(self.e,ensure_ascii=False,separators=(',',':'))+'\n')
  coverage={str(id):{s['plane']:[n for n,f in enumerate(s['frames'],1) if any(p['structure']==id for p in self.e['seriesSlices'][s['id']][f['annotation']]['points'])] for s in self.s.values()} for id in self.defs}
  report.append({'module':self.mod,'sourceDataSha256':hashlib.sha256((A/(self.mod+'-data.json')).read_bytes()).hexdigest(),'sourceLabelsSha256':hashlib.sha256((A/(self.mod+'-labels.json')).read_bytes()).hexdigest(),'points':self.points,'ribbons':self.ribbons,'coverage':coverage,'presentation':self.e['pointPresentation']})
