for id,name,note in [
 (149101,'Прямая мышца бедра · прямое сухожилие у НППО','Ожидаемое начало прямой головки на нижней передней подвздошной ости (НППО). Не верхняя передняя ость, от которой начинается портняжная.'),
 (149102,'Прямая мышца бедра · отражённое сухожилие','Непрямая головка начинается в надвертлужной борозде и связана с верхней капсулой. Тонкая граница с капсулой здесь не выделена независимо.'),
 (149103,'Хамстринги · общее начало ST/BF','Общее проксимальное сухожилие полусухожильной и длинной головки двуглавой на седалищном бугре. Не вся задняя поверхность седалищной кости; отдельные волокна не сегментированы.'),
 (149104,'Полуперепончатая · проксимальное начало','Проксимальная область начала сухожилия на переднелатеральной части седалищного бугра, отдельно от общего начала ST/BF.'),
 (149105,'Длинная приводящая · лобковое начало','Поверхностная сухожильно-апоневротическая область у тела лобковой кости рядом с лобковым бугорком; связь с прямой мышцей живота. Не вся масса приводящей мышцы.'),
 (149106,'Тонкая мышца · проксимальное начало','Тонкое плоское проксимальное сухожильно-апоневротическое начало на теле/нижней ветви лобковой кости. Разделение с соседними приводящими на этих кадрах ориентировочное.'),
 (149107,'Большая приводящая · седалищное начало','Область начала седалищной части большой приводящей у седалищного бугра; медиальнее хамстрингов. Дистальное сухожилие к приводящему бугорку в зоне колена не входит в поле ТБС.'),
 (149108,'Портняжная · начало у ВППО','Ожидаемое короткое сухожильное начало от верхней передней подвздошной ости (ВППО), с передней стороны. Дистальное прикрепление к гусиной лапке за пределами этой серии.'),
 (149109,'Напрягатель широкой фасции · проксимальный апоневроз','Проксимальная область у ВППО и прилежащего наружного края подвздошного гребня. Это короткий сухожильно-апоневротический переход; не длинное свободное сухожилие.'),
 (149110,'Большая ягодичная · бедренное прикрепление','Ожидаемая область глубокой части сухожильного прикрепления к ягодичной бугристости проксимального бедра. Значительная часть волокон также переходит в подвздошно-большеберцовый тракт; не считать большой вертел её основным прикреплением.'),
 (149111,'Гребенчатая · дистальный апоневроз','Ожидаемая область короткого сухожильно-апоневротического прикрепления к гребенчатой линии бедренной кости, ниже малого вертела. Отдельный длинный сухожильный пучок на данном наборе не прослежен.')]:h.define(id,name,note,14701)
